nResponse([ 'ok' => true, 'recording' => $recording, 'demos' => array_values($demos), ]); } catch (Throwable $e) { Log::error('[RustPlayerManager] getDemos error: ' . $e->getMessage()); return new JsonResponse(['ok' => true, 'recording' => false, 'demos' => []]); } } public function demoAction(RustControlRequest $request, Server $server): JsonResponse { try { $files = new ServerFiles($server); $action = strtolower(trim((string) $request->input('action', ''))); $name = trim((string) $request->input('name', '')); if ($action === 'record') { $demoName = substr(preg_replace('/[^a-zA-Z0-9_-]/', '', $name) ?? '', 0, 64) ?: ('demo_' . time()); try { $files->sendCommand("record {$demoName}"); } catch (Throwable) {} Cache::forever("dezerx:rust:demo_recording:{$server->uuid}", true); return new JsonResponse([ 'ok' => true, 'recording' => true, 'name' => $demoName, 'message' => "Started recording demo: {$demoName}", ]); } if ($action === 'stop') { try { $files->sendCommand("stop"); } catch (Throwable) {} Cache::forget("dezerx:rust:demo_recording:{$server->uuid}"); return new JsonResponse([ 'ok' => true, 'recording' => false, 'message' => "Stopped recording demo.", ]); } if ($action === 'delete') { if (!$request->user()->can(Permission::ACTION_FILE_DELETE, $server)) { return new JsonResponse(['ok' => false, 'error' => 'You need permission to delete files for that.'], 403); } $path = '/' . ltrim(trim((string) $request->input('path', '')), '/'); $dir = dirname($path); $file = basename($path); $identity = (string) ($server->variables()->where('env_variable', 'SERVER_IDENTITY')->first()?->server_value ?? 'rust') ?: 'rust'; $allowed = ["/server/{$identity}/demos", '/server/rust/demos', '/demos', "/server/{$identity}", '/server/rust', '/']; if (!in_array($dir, $allowed, true) || preg_match('/^[A-Za-z0-9_.-]{1,96}\.dem$/i', $file) !== 1 || str_starts_with($file, '.')) { return $this->reject('That is not a demo file.'); } $files->deletePaths($dir, [$file]); return new JsonResponse(['ok' => true, 'message' => "Deleted {$file}."]); } return new JsonResponse(['ok' => false, 'error' => 'Invalid demo action'], 422); } catch (Throwable $e) { Log::error('[RustPlayerManager] demoAction error: ' . $e->getMessage()); return new JsonResponse(['ok' => false, 'error' => 'Demo action failed: ' . $e->getMessage()], 422); } } public function getBans(RustReadRequest $request, Server $server): JsonResponse { try { $files = new ServerFiles($server); $authData = $this->parseAuthConfigs($files, $server); $stateData = $this->readBridgeState($files, $server); $history = $this->getBanHistory($files, $server); $activeBansMap = []; if (!empty($authData['bans'])) { foreach ($authData['bans'] as $steamId => $info) { $steamId = (string) $steamId; $activeBansMap[$steamId] = [ 'steamId' => $steamId, 'name' => $info['name'] ?? 'Banned Player', 'avatar' => RustSteamService::getAvatar($steamId), 'reason' => !empty($info['reason']) ? $info['reason'] : 'Violating server rules', 'duration' => 0, 'expiresAt' => $info['expiry'] ?? 0, 'bannedAt' => time(), 'source' => 'bans.cfg', ]; } } if ($stateData !== null && isset($stateData['bans']) && is_array($stateData['bans'])) { foreach ($stateData['bans'] as $b) { $sId = (string) ($b['steamId'] ?? ''); if (empty($sId)) continue; $expiry = isset($b['expiry']) ? (int) $b['expiry'] : 0; $activeBansMap[$sId] = [ 'steamId' => $sId, 'name' => !empty($b['name']) ? $b['name'] : ($activeBansMap[$sId]['name'] ?? 'Banned Player'), 'avatar' => RustSteamService::getAvatar($sId), 'reason' => !empty($b['reason']) ? $b['reason'] : ($activeBansMap[$sId]['reason'] ?? 'Violating server rules'), 'duration' => 0, 'expiresAt' => $expiry, 'bannedAt' => $activeBansMap[$sId]['bannedAt'] ?? time(), 'source' => 'bridge', ]; } } $historyUpdated = false; $dedupHistory = []; $seenHistoryKeys = []; foreach ($history as $h) { $sId = (string) ($h['steamId'] ?? ''); $bAt = (int) ($h['bannedAt'] ?? 0); $key = "{$sId}:" . round($bAt / 120); if (!empty($sId) && isset($seenHist